const HUB_SEARCH_STYLES = HUB_DESIGN_STYLES + `
dialog{position:fixed;inset:0;margin:auto;width:min(880px,calc(100vw - 32px));max-width:none;max-height:90vh;max-height:90dvh;padding:0;border:1px solid var(--hub-line-strong);border-radius:18px;background:var(--hub-canvas);color:var(--hub-ink);box-shadow:0 32px 90px #16181c33;font:inherit;overflow:auto}
dialog::backdrop{background:#1c1e2159;backdrop-filter:blur(3px)}dialog header{padding:22px 28px 18px}dialog h2{font-size:24px;letter-spacing:-.025em}.hub-search-content{padding:20px 28px 26px}.hub-search-intro{color:var(--hub-muted);max-width:620px;margin:0 0 18px}.hub-query{font-size:16px!important;background:var(--hub-surface)!important;padding:13px 16px!important}.hub-filters{display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin:14px 0 20px}.hub-filters label{display:grid;gap:5px;font-size:11px;letter-spacing:.04em;text-transform:uppercase;font-weight:650;color:var(--hub-muted)}.hub-filters select{min-width:160px;background:var(--hub-surface)}.hub-filters button{margin-left:auto}.hub-search-summary{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.hub-search-summary strong{font-size:14px}.hub-result{background:var(--hub-surface);border:1px solid var(--hub-line);border-radius:12px;padding:16px 18px;margin-bottom:10px}.hub-result-top{display:flex;gap:10px;justify-content:space-between;align-items:center;margin-bottom:9px}.hub-bank{font-size:10px;font-weight:650;letter-spacing:.1em;text-transform:uppercase;color:var(--hub-muted)}.hub-result h3{font-size:16px;letter-spacing:-.01em;text-transform:none;color:var(--hub-ink);margin:0 0 5px;overflow-wrap:anywhere}.hub-result p{overflow-wrap:anywhere;margin:4px 0}.hub-result-meta{font-size:11px;color:var(--hub-muted);display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.hub-result a{font-size:12px}.hub-state{font-size:10px;font-weight:550;padding:3px 9px;border-radius:99px;background:var(--hub-canvas);border:1px solid var(--hub-line);color:var(--hub-ink-soft);white-space:nowrap}.hub-state.available,.hub-state.added{color:var(--hub-accent);background:var(--hub-tint);border-color:#cadfd6}.hub-state.review{color:var(--hub-warn-ink);background:var(--hub-warn-bg);border-color:#efdcb8}.hub-empty{padding:36px 18px;text-align:center;color:var(--hub-muted);background:var(--hub-surface);border:1px dashed var(--hub-line-strong);border-radius:12px}.hub-coverage{margin-top:20px;color:var(--hub-muted);font-size:12px}.hub-coverage summary{cursor:pointer}.hub-coverage ul{list-style:none;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:8px}.hub-coverage li{display:flex;justify-content:space-between;gap:12px;padding:8px 10px;background:var(--hub-surface);border:1px solid var(--hub-line);border-radius:8px}.hub-more{width:100%;margin-top:5px}.hub-search-error{color:var(--hub-danger);font-size:12px}.hub-close{font-size:16px;padding:6px 12px}
@media(max-width:600px){dialog{width:calc(100vw - 16px);max-height:94dvh;border-radius:14px}dialog header{padding:18px}.hub-search-content{padding:16px}.hub-filters{gap:8px}.hub-filters label{flex:1;min-width:120px}.hub-filters select{width:100%;min-width:0}.hub-filters button{margin-left:0}.hub-coverage ul{grid-template-columns:1fr}.hub-result{padding:14px}.hub-search-summary{align-items:flex-start}.hub-search-summary span{max-width:140px;text-align:right}}
`;
